export const marker = true;

// A library from the project checks values with the classes of its own realm,
// as jose does for a key.
export function keyLength(key) {
  if (!(key instanceof Uint8Array)) throw new TypeError('key must be a Uint8Array');
  return key.byteLength;
}

export function realmChecks(values) {
  return {
    arrayBuffer: values.arrayBuffer instanceof ArrayBuffer,
    dataView: values.dataView instanceof DataView,
    float64: values.float64 instanceof Float64Array,
    bigInt64: values.bigInt64 instanceof BigInt64Array,
    typeError: values.typeError instanceof TypeError && values.typeError instanceof Error,
    encoded: values.encoded instanceof Uint8Array
  };
}

export function hostBytes() {
  return new Uint8Array(4);
}
